public sealed class SupplierRmaCapaGovernanceReview{public int Id{get;init;}public string Outcome{get;init;}="";public string EvaluationStatus{get;init;}="";public int TotalActions{get;init;}public int OverdueActions{get;init;}public double OnTimePercentage{get;init;}public double AverageCompletionDays{get;init;}public string Notes{get;init;}="";public string Decisions{get;init;}="";public string Reviewer{get;init;}="";public string ReviewDate{get;init;}="";public string NextReviewDate{get;init;}="";public string ReportPath{get;init;}="";public string ApprovalStatus{get;init;}="Bozza";public string Approver{get;init;}="";public string ApprovalDate{get;init;}="";public string ApprovalNotes{get;init;}="";public int Revision{get;init;}=1;public bool IsLocked=>ApprovalStatus=="Approvato";public bool ReportAvailable=>File.Exists(ReportPath);public bool IsOverdue=>DateTime.TryParse(NextReviewDate,out var d)&&d.Date<DateTime.Today;public bool IsDueSoon=>DateTime.TryParse(NextReviewDate,out var d)&&d.Date>=DateTime.Today&&d.Date<=DateTime.Today.AddDays(30);}
public sealed class SupplierRmaCapaGovernanceReviewApprovalEvent{public int Id{get;init;}public int ReviewId{get;init;}public string EventType{get;init;}="";public string OldStatus{get;init;}="";public string NewStatus{get;init;}="";public string Notes{get;init;}="";public string CreatedAt{get;init;}="";public string CreatedBy{get;init;}="";}
public sealed class SupplierRmaCapaGovernanceReviewService
{
 private readonly string _cs;private readonly SettingsService _settings=new();
 public SupplierRmaCapaGovernanceReviewService(string? db=null){var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"AccyourateEnterpriseX");Directory.CreateDirectory(folder);_cs=$"Data Source={db??Path.Combine(folder,"accyourate-assets.db")}";using var c=Open();using var q=c.CreateCommand();q.CommandText="CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceReviews(Id INTEGER PRIMARY KEY AUTOINCREMENT,Outcome TEXT NOT NULL,EvaluationStatus TEXT NOT NULL,TotalActions INTEGER NOT NULL,OverdueActions INTEGER NOT NULL,OnTimePercentage REAL NOT NULL,AverageCompletionDays REAL NOT NULL,Notes TEXT NOT NULL,Decisions TEXT NOT NULL,Reviewer TEXT NOT NULL,ReviewDate TEXT NOT NULL,NextReviewDate TEXT NOT NULL,ReportPath TEXT NOT NULL);CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceReviewNotifications(NotificationKey TEXT PRIMARY KEY,ReviewId INTEGER NOT NULL,CreatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceReviewApprovalEvents(Id INTEGER PRIMARY KEY AUTOINCREMENT,ReviewId INTEGER NOT NULL,EventType TEXT NOT NULL,OldStatus TEXT NOT NULL,NewStatus TEXT NOT NULL,Notes TEXT NOT NULL,CreatedAt TEXT NOT NULL,CreatedBy TEXT NOT NULL);";q.ExecuteNonQuery();Ensure(c,"ApprovalStatus","TEXT NOT NULL DEFAULT 'Bozza'");Ensure(c,"Approver","TEXT NOT NULL DEFAULT ''");Ensure(c,"ApprovalDate","TEXT NOT NULL DEFAULT ''");Ensure(c,"ApprovalNotes","TEXT NOT NULL DEFAULT ''");Ensure(c,"Revision","INTEGER NOT NULL DEFAULT 1");}
 public IReadOnlyList<SupplierRmaCapaGovernanceReview> GetAll(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,Outcome,EvaluationStatus,TotalActions,OverdueActions,OnTimePercentage,AverageCompletionDays,Notes,Decisions,Reviewer,ReviewDate,NextReviewDate,ReportPath,ApprovalStatus,Approver,ApprovalDate,ApprovalNotes,Revision FROM SupplierRmaCapaGovernanceReviews ORDER BY Id DESC;";using var r=q.ExecuteReader();var v=new List<SupplierRmaCapaGovernanceReview>();while(r.Read())v.Add(new(){Id=r.GetInt32(0),Outcome=r.GetString(1),EvaluationStatus=r.GetString(2),TotalActions=r.GetInt32(3),OverdueActions=r.GetInt32(4),OnTimePercentage=r.GetDouble(5),AverageCompletionDays=r.GetDouble(6),Notes=r.GetString(7),Decisions=r.GetString(8),Reviewer=r.GetString(9),ReviewDate=r.GetString(10),NextReviewDate=r.GetString(11),ReportPath=r.GetString(12),ApprovalStatus=r.GetString(13),Approver=r.GetString(14),ApprovalDate=r.GetString(15),ApprovalNotes=r.GetString(16),Revision=r.GetInt32(17)});return v;}
 public SupplierRmaCapaGovernanceReview Create(string outcome,string notes,string decisions,string reviewer,string nextReview,SupplierRmaCapaGovernanceActionAnalytics analytics,SupplierRmaCapaGovernanceGoalEvaluation evaluation){if(outcome is not("Confermato" or "Con riserva" or "Non conforme"))throw new InvalidOperationException("Esito non valido.");if(string.IsNullOrWhiteSpace(notes)||string.IsNullOrWhiteSpace(decisions)||string.IsNullOrWhiteSpace(reviewer)||!DateTime.TryParse(nextReview,out var next))throw new InvalidOperationException("Note, decisioni, responsabile e prossimo riesame sono obbligatori.");using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO SupplierRmaCapaGovernanceReviews(Outcome,EvaluationStatus,TotalActions,OverdueActions,OnTimePercentage,AverageCompletionDays,Notes,Decisions,Reviewer,ReviewDate,NextReviewDate,ReportPath) VALUES($o,$e,$t,$s,$p,$m,$n,$d,$r,$at,$next,'');SELECT last_insert_rowid();";q.Parameters.AddWithValue("$o",outcome);q.Parameters.AddWithValue("$e",evaluation.OverallStatus);q.Parameters.AddWithValue("$t",analytics.Total);q.Parameters.AddWithValue("$s",analytics.Overdue);q.Parameters.AddWithValue("$p",analytics.OnTimePercentage);q.Parameters.AddWithValue("$m",analytics.AverageCompletionDays);q.Parameters.AddWithValue("$n",notes.Trim());q.Parameters.AddWithValue("$d",decisions.Trim());q.Parameters.AddWithValue("$r",reviewer.Trim());q.Parameters.AddWithValue("$at",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$next",next.ToString("yyyy-MM-dd"));var id=Convert.ToInt32(q.ExecuteScalar());var item=GetAll().First(x=>x.Id==id);var report=GeneratePdf(item);using var update=c.CreateCommand();update.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ReportPath=$p WHERE Id=$id;";update.Parameters.AddWithValue("$p",report);update.Parameters.AddWithValue("$id",id);update.ExecuteNonQuery();return GetAll().First(x=>x.Id==id);}
 public void Submit(int id,string approver,string user){if(string.IsNullOrWhiteSpace(approver))throw new InvalidOperationException("Indica l'approvatore.");var item=Find(id);if(item.ApprovalStatus is not("Bozza" or "Rifiutato" or "Riaperto"))throw new InvalidOperationException("Il riesame non puo essere inviato in approvazione.");if(string.Equals(item.Reviewer,approver,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Autore e approvatore devono essere persone diverse.");using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ApprovalStatus='In approvazione',Approver=$a,ApprovalNotes='',ApprovalDate='' WHERE Id=$id;";q.Parameters.AddWithValue("$a",approver.Trim());q.Parameters.AddWithValue("$id",id);q.ExecuteNonQuery();Event(c,id,"Invio in approvazione",item.ApprovalStatus,"In approvazione",$"Approvatore: {approver}",user);new NotificationService().Publish("Riesame Governance CAPA da approvare",$"Riesame #{id:D6} inviato a {approver}.",NotificationCategory.Asset,NotificationPriority.High,user,"open-rma-corrective-actions",id.ToString());}
 public void Decide(int id,bool approved,string notes,string user){var item=Find(id);if(item.ApprovalStatus!="In approvazione")throw new InvalidOperationException("Il riesame non e in approvazione.");if(!string.Equals(item.Approver,user,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Solo l'approvatore designato puo registrare la decisione.");if(!approved&&string.IsNullOrWhiteSpace(notes))throw new InvalidOperationException("La motivazione del rifiuto e obbligatoria.");var status=approved?"Approvato":"Rifiutato";using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ApprovalStatus=$s,ApprovalDate=$d,ApprovalNotes=$n WHERE Id=$id;";q.Parameters.AddWithValue("$s",status);q.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$n",notes.Trim());q.Parameters.AddWithValue("$id",id);q.ExecuteNonQuery();Event(c,id,"Decisione approvazione",item.ApprovalStatus,status,notes,user);var updated=Find(id);var report=GeneratePdf(updated);using var p=c.CreateCommand();p.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ReportPath=$p WHERE Id=$id;";p.Parameters.AddWithValue("$p",report);p.Parameters.AddWithValue("$id",id);p.ExecuteNonQuery();}
 public void Reopen(int id,string reason,string user){if(string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("Indica la motivazione della riapertura.");var item=Find(id);if(item.ApprovalStatus!="Approvato")throw new InvalidOperationException("Solo un riesame approvato puo essere riaperto.");using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceReviews SET ApprovalStatus='Riaperto',ApprovalNotes=$n,Revision=Revision+1 WHERE Id=$id;";q.Parameters.AddWithValue("$n",reason.Trim());q.Parameters.AddWithValue("$id",id);q.ExecuteNonQuery();Event(c,id,"Riapertura controllata","Approvato","Riaperto",reason,user);}
 public IReadOnlyList<SupplierRmaCapaGovernanceReviewApprovalEvent> ApprovalHistory(int id){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,ReviewId,EventType,OldStatus,NewStatus,Notes,CreatedAt,CreatedBy FROM SupplierRmaCapaGovernanceReviewApprovalEvents WHERE ReviewId=$id ORDER BY Id DESC;";q.Parameters.AddWithValue("$id",id);using var r=q.ExecuteReader();var v=new List<SupplierRmaCapaGovernanceReviewApprovalEvent>();while(r.Read())v.Add(new(){Id=r.GetInt32(0),ReviewId=r.GetInt32(1),EventType=r.GetString(2),OldStatus=r.GetString(3),NewStatus=r.GetString(4),Notes=r.GetString(5),CreatedAt=r.GetString(6),CreatedBy=r.GetString(7)});return v;}
 public int PublishAlerts(NotificationService? n=null){n??=new NotificationService();var count=0;foreach(var x in GetAll().Where(x=>x.IsOverdue||x.IsDueSoon)){var key=$"capa-governance-review:{x.Id}:{(x.IsOverdue?"overdue":"due")}:{DateTime.Today:yyyyMMdd}";using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM SupplierRmaCapaGovernanceReviewNotifications WHERE NotificationKey=$k;";q.Parameters.AddWithValue("$k",key);if(Convert.ToInt32(q.ExecuteScalar())>0)continue;n.Publish(x.IsOverdue?"Riesame Governance CAPA scaduto":"Riesame Governance CAPA in scadenza",$"Prossimo riesame previsto il {Date(x.NextReviewDate)}.",NotificationCategory.Asset,x.IsOverdue?NotificationPriority.Critical:NotificationPriority.High,"Riesame Governance CAPA","open-rma-corrective-actions",x.Id.ToString());using var a=c.CreateCommand();a.CommandText="INSERT INTO SupplierRmaCapaGovernanceReviewNotifications(NotificationKey,ReviewId,CreatedAt) VALUES($k,$id,$d);";a.Parameters.AddWithValue("$k",key);a.Parameters.AddWithValue("$id",x.Id);a.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));a.ExecuteNonQuery();count++;}return count;}
 private string GeneratePdf(SupplierRmaCapaGovernanceReview x){var s=_settings.Load();var t=s.DocumentTemplate??new DocumentTemplateSettings();var d=new SimplePdfDocument{Title="Verbale riesame Governance CAPA"};Brand(d,s,t,$"CAPA-REV-{x.Id:D6}-R{x.Revision}");d.AddTitle("Verbale riesame periodico Governance CAPA");d.AddKeyValue("Numero riesame",x.Id.ToString("D6"));d.AddKeyValue("Revisione",x.Revision.ToString());d.AddKeyValue("Data",Date(x.ReviewDate));d.AddKeyValue("Responsabile",x.Reviewer);d.AddKeyValue("Prossimo riesame",Date(x.NextReviewDate));d.AddStatus("Esito del riesame",x.Outcome);d.AddStatus("Valutazione indicatori",x.EvaluationStatus);d.AddHeading("Approvazione");d.AddKeyValue("Stato",x.ApprovalStatus);d.AddKeyValue("Approvatore",string.IsNullOrWhiteSpace(x.Approver)?"Non assegnato":x.Approver);d.AddKeyValue("Data decisione",Date(x.ApprovalDate));if(!string.IsNullOrWhiteSpace(x.ApprovalNotes))d.AddText($"Note approvazione: {x.ApprovalNotes}",9);d.AddHeading("Indicatori consolidati");d.AddKeyValue("Azioni totali",x.TotalActions.ToString());d.AddKeyValue("Azioni scadute",x.OverdueActions.ToString());d.AddKeyValue("Completate entro scadenza",$"{x.OnTimePercentage:N1}%");d.AddKeyValue("Tempo medio completamento",$"{x.AverageCompletionDays:N1} giorni");d.AddHeading("Osservazioni");d.AddText(x.Notes);d.AddHeading("Decisioni e azioni conseguenti");d.AddText(x.Decisions);d.AddSignaturePair("Responsabile qualita","Approvatore");var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Accyourate Enterprise X","Riesami Governance CAPA");return new PdfExportService().Export(d,folder,$"Riesame-Governance-CAPA-{x.Id:D6}-R{x.Revision}-{DateTime.Now:yyyyMMdd-HHmmss}");}
 private SupplierRmaCapaGovernanceReview Find(int id)=>GetAll().FirstOrDefault(x=>x.Id==id)??throw new InvalidOperationException("Riesame non trovato.");private static string Date(string v)=>DateTime.TryParse(v,out var d)?d.ToString("dd/MM/yyyy HH:mm"):string.IsNullOrWhiteSpace(v)?"Non disponibile":v;private static void Ensure(SqliteConnection c,string column,string definition){using var q=c.CreateCommand();q.CommandText="PRAGMA table_info(SupplierRmaCapaGovernanceReviews);";using var r=q.ExecuteReader();while(r.Read())if(string.Equals(r.GetString(1),column,StringComparison.OrdinalIgnoreCase))return;r.Close();using var a=c.CreateCommand();a.CommandText=$"ALTER TABLE SupplierRmaCapaGovernanceReviews ADD COLUMN {column} {definition};";a.ExecuteNonQuery();}private static void Event(SqliteConnection c,int id,string type,string oldStatus,string newStatus,string notes,string user){using var q=c.CreateCommand();q.CommandText="INSERT INTO SupplierRmaCapaGovernanceReviewApprovalEvents(ReviewId,EventType,OldStatus,NewStatus,Notes,CreatedAt,CreatedBy) VALUES($id,$t,$o,$n,$x,$d,$u);";q.Parameters.AddWithValue("$id",id);q.Parameters.AddWithValue("$t",type);q.Parameters.AddWithValue("$o",oldStatus);q.Parameters.AddWithValue("$n",newStatus);q.Parameters.AddWithValue("$x",notes??"");q.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$u",user);q.ExecuteNonQuery();}
 private static void Brand(SimplePdfDocument d,ApplicationSettings s,DocumentTemplateSettings t,string code){d.Branding.CompanyName=string.IsNullOrWhiteSpace(s.Company.LegalName)?s.Company.CompanyName:s.Company.LegalName;d.Branding.CompanyDetailLines.AddRange(new[]{s.Company.Address,string.Join(" ",new[]{s.Company.City,s.Company.Province}.Where(v=>!string.IsNullOrWhiteSpace(v))),string.Join(" - ",new[]{s.Company.Phone,s.Company.Email}.Where(v=>!string.IsNullOrWhiteSpace(v)))}.Where(v=>!string.IsNullOrWhiteSpace(v)));d.Branding.HeaderLayout=t.HeaderLayout;d.Branding.LogoPath=s.Company.LogoPath;d.Branding.LogoSize=t.LogoSize;d.Branding.LogoPosition=t.LogoPosition;d.Branding.PrimaryColor=t.PrimaryColor;d.Branding.DocumentLabel="RIESAME GOVERNANCE CAPA";d.Branding.DocumentCode=code;d.Branding.DocumentVersion=t.DocumentVersion;d.Branding.FooterText=t.FooterText;d.Branding.ConfidentialityText=t.ConfidentialityText;d.Branding.ShowLogo=t.ShowLogo;d.Branding.ShowCompanyDetails=t.ShowCompanyDetails;d.Branding.ShowDocumentMetadata=t.ShowDocumentMetadata;d.Branding.ShowFooter=t.ShowFooter;d.Branding.ShowPageNumber=t.ShowPageNumber;d.Branding.ShowPrintTimestamp=t.ShowPrintTimestamp;}private SqliteConnection Open(){var c=new SqliteConnection(_cs);c.Open();return c;}
